python3 -c 'import sys,json,re,shlex,os,subprocess
def cur():
    d=os.environ.get("CLAUDE_PROJECT_DIR") or "."
    try:
        return subprocess.run(["git","-C",d,"symbolic-ref","--short","HEAD"],capture_output=True,text=True,timeout=3).stdout.strip()
    except Exception:
        return ""
try:
    data=json.load(sys.stdin)
except Exception:
    sys.exit(0)
if (data.get("tool_name") or "")!="Bash":
    sys.exit(0)
cmd=(data.get("tool_input") or {}).get("command") or ""
hit=False
for seg in re.split(r"[;|&\n]",cmd):
    try:
        toks=shlex.split(seg)
    except Exception:
        toks=seg.split()
    g=0
    while g<len(toks) and (re.match(r"^[A-Za-z_][A-Za-z_0-9]*=",toks[g]) or toks[g] in ("sudo","env","command","time","nohup")):
        g+=1
    if g>=len(toks) or not (toks[g]=="git" or toks[g].endswith("/git")):
        continue
    j=g+1
    while j<len(toks):
        if toks[j] in ("-C","-c","--git-dir","--work-tree","--namespace","--exec-path"):
            j+=2
        elif toks[j].startswith("-"):
            j+=1
        else:
            break
    if j>=len(toks) or toks[j]!="push":
        continue
    pos=[t for t in toks[j+1:] if not t.startswith("-")]
    if len(pos)<2:
        if cur()=="main":
            hit=True
    else:
        for r in pos[1:]:
            d=re.sub(r"^refs/heads/","",r.split(":")[-1].lstrip("+"))
            if d in ("HEAD","@"):
                d=cur()
            if d=="main":
                hit=True
if hit:
    sys.stderr.write("Blocked: never push to main directly (CLAUDE.md, Repository etiquette). Admin bypass means the push would succeed. Instead: git switch -c <type>/<slug>, push that branch, gh pr create, then gh pr merge --rebase once ci is green.")
    sys.exit(2)
sys.exit(0)
'

python3 -c 'import sys,json,re,shlex,os
try:
    data=json.load(sys.stdin)
except Exception:
    sys.exit(0)
if (data.get("tool_name") or "")!="Bash":
    sys.exit(0)
cmd=(data.get("tool_input") or {}).get("command") or ""
home=os.path.expanduser("~")
Q=chr(34)+chr(39)
OK=(".env.example",".env.sample",".env.template")
def bad(tok):
    t=tok.strip(Q)
    if not t:
        return ""
    t=re.sub(r"^(~|\$HOME|\$\{HOME\})(?=/|$)",home,t)
    p=t
    while p.startswith("./"):
        p=p[2:]
    parts=[x for x in p.split("/") if x and x!="."]
    if not parts:
        return ""
    b=parts[-1]
    if b==".env" or (b.startswith(".env.") and b not in OK):
        return t
    if "secrets" in parts[:-1]:
        return t
    if t.startswith("/"):
        for d in (".ssh",".aws",".config"):
            if t.startswith(home+"/"+d+"/"):
                return t
    return ""
for seg in re.split(r"[;|&\n]",cmd):
    try:
        toks=shlex.split(seg)
    except Exception:
        toks=seg.split()
    for tok in toks:
        h=bad(tok)
        if h:
            sys.stderr.write("Blocked: "+h+" is a secret path. permissions.deny in .claude/settings.json blocks the Read tool on .env/.env.*/secrets/**/~/.ssh/~/.aws/~/.config, and this Bash command would read the same secrets around that rule. If you only need to know which variables exist, read .env.example instead.")
            sys.exit(2)
sys.exit(0)
'
